@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PermissionHelpScreen(onNavigateBack: () -> Unit) {
    val context = LocalContext.current
    val lifecycleOwner = LocalLifecycleOwner.current
    val controller: DeviceController = koinInject()
    var active by remember { mutableStateOf(controller.isAvailable) }
    var overlay by remember { mutableStateOf(Settings.canDrawOverlays(context)) }
    var mic by remember { mutableStateOf(false) }
    var deviceAccess by remember { mutableStateOf(ActionConfirmation.isDeviceAccessGranted(context)) }
    var launchError by remember { mutableStateOf<String?>(null) }
    fun refresh() {
        deviceAccess = ActionConfirmation.isDeviceAccessGranted(context)
        active = controller.isAvailable
        overlay = Settings.canDrawOverlays(context)
        mic = ContextCompat.checkSelfPermission(context, Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED
    }
    fun open(action: String, withPackage: Boolean = false) {
        try {
            context.startActivity(Intent(action).apply {
                if (withPackage) data = Uri.parse("package:${context.packageName}")
            })
            launchError = null
        } catch (_: Exception) {
            launchError = "Не удалось открыть этот раздел. Откройте его вручную в настройках телефона."
        }
    }
    DisposableEffect(lifecycleOwner) {
        refresh()
        val observer = LifecycleEventObserver { _, event ->
            if (event == Lifecycle.Event.ON_RESUME) refresh()
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
    }
    Scaffold(topBar = {
        TopAppBar(title = { Text("Разрешения Джарвиса") }, navigationIcon = {
            TextButton(onClick = onNavigateBack) { Text("Назад") }
        })
    }) { padding ->
        Column(Modifier.padding(padding).fillMaxSize().verticalScroll(rememberScrollState()).padding(20.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)) {
            Text("Управление экраном: ${if (deviceAccess) "разрешено без повторных запросов" else "потребуется подтверждение"}")
            if (deviceAccess) {
                OutlinedButton(onClick = { ActionConfirmation.revokeDeviceAccess(context); refresh() }) { Text("Отозвать разрешение управления экраном") }
            }
            Text("Состояние разрешений", style = MaterialTheme.typography.titleMedium)
            Text("Специальные возможности: ${if (active) "служба работает" else "служба не подключена"}")
            Text("Поверх приложений: ${if (overlay) "разрешено" else "не разрешено"}")
            Text("Микрофон: ${if (mic) "разрешён" else "не разрешён"}")
            Text("Специальные возможности позволяют читать содержимое экрана, делать снимки и выполнять нажатия, ввод текста и жесты по вашим командам. Данные экрана могут отправляться подключённой модели для выполнения задачи.")
            Text("Если Android пишет «Доступ для приложения запрещён»", style = MaterialTheme.typography.titleMedium)
            Text("1. Откройте сведения о Джарвисе кнопкой ниже.\n2. Нажмите меню ⋮ в правом верхнем углу.\n3. Выберите «Разрешить ограниченные настройки» и подтвердите действие на телефоне.\n4. Вернитесь в специальные возможности, откройте «Установленные приложения» → «Джарвис» и включите службу.")
            Button(onClick = { open(Settings.ACTION_APPLICATION_DETAILS_SETTINGS, true) }, modifier = Modifier.fillMaxWidth()) { Text("Сведения о Джарвисе") }
            Button(onClick = { open(Settings.ACTION_ACCESSIBILITY_SETTINGS) }, modifier = Modifier.fillMaxWidth()) { Text("Специальные возможности") }
            Text("Это системное ограничение для некоторых приложений, установленных из APK. Приложение не может снять его самостоятельно. Если пункта нет, проверьте ограничения рабочего профиля или администратора устройства. Названия пунктов зависят от версии Android.")
            OutlinedButton(onClick = { open(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, true) }, modifier = Modifier.fillMaxWidth()) { Text("Разрешить поверх приложений") }
            OutlinedButton(onClick = { open(Settings.ACTION_APPLICATION_DETAILS_SETTINGS, true) }, modifier = Modifier.fillMaxWidth()) { Text("Настроить микрофон") }
            Text("Микрофон включается в разделе «Разрешения» сведений о приложении.")
            TextButton(onClick = { refresh() }) { Text("Обновить состояние") }
            TextButton(onClick = {
                try { context.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse("https://support.google.com/android/answer/12623953"))) }
                catch (_: Exception) { launchError = "Не удалось открыть инструкцию Google." }
            }) { Text("Инструкция Google") }
            launchError?.let { Text(it, color = MaterialTheme.colorScheme.error) }
        }
    }
}

package io.clawdroid.diagnostics

import android.content.Context
import android.util.AtomicFile
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.json.Json
import java.io.File

/** No free text input: only constrained categories and numeric metadata. */
object DiagnosticEvents {
    @Serializable data class Event(val time: Long, val component: String, val code: String, val status: Int? = null, val durationMs: Long? = null)
    private val events = ArrayDeque<Event>()
    private var store: AtomicFile? = null
    private val components = setOf("openai", "tool", "assistant", "websocket")
    private val codes = setOf("save_failure", "connection_started", "connected", "disconnected", "authentication", "quota", "network", "model", "region", "permission", "rate_limit", "local_gateway_auth", "local_gateway_network", "invalid_request", "context", "upstream", "unknown", "started", "stopped", "success", "error", "cancelled", "screenshot_secure_window", "screenshot_interval", "screenshot_access_denied", "screenshot_capture_error", "screenshot_started", "screenshot_success", "screenshot_error", "screenshot_cancelled", "ui_started", "ui_success", "ui_error", "ui_cancelled", "other_started", "other_success", "other_error", "other_cancelled")
    @Synchronized fun initialize(context: Context) {
        if (store != null) return
        store = AtomicFile(File(context.filesDir, "test-diagnostics.json"))
        val saved = runCatching { Json.decodeFromString<List<Event>>(store!!.openRead().use { it.readBytes().toString(Charsets.UTF_8) }) }.getOrDefault(emptyList())
        val current = events.toList()
        events.clear()
        (saved + current).filter { valid(it) }.takeLast(200).forEach { events.addLast(it) }
        persist()
    }
    private fun valid(event: Event) = event.component in components && event.code in codes && (event.status == null || event.status in 100..599) && (event.durationMs == null || event.durationMs in 0..86400000)
    @Synchronized fun record(component: String, code: String, status: Int? = null, durationMs: Long? = null) {
        val event = Event(System.currentTimeMillis(), component, code, status, durationMs)
        require(valid(event)) { "Invalid diagnostic category" }
        events.addLast(event)
        while (events.size > 200) events.removeFirst()
        persist()
    }
    private fun persist() {
        val target = store ?: return
        runCatching {
            val stream = target.startWrite()
            try { stream.write(Json.encodeToString(events.toList()).toByteArray()); target.finishWrite(stream) }
            catch (error: Exception) { target.failWrite(stream); throw error }
        }
    }
    @Synchronized fun snapshot(): List<Event> = events.toList()
}

package io.clawdroid.assistant

import android.content.Context
import android.content.SharedPreferences
import io.clawdroid.core.data.remote.dto.ToolRequest
import io.mockk.*
import kotlinx.coroutines.test.runTest
import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.Test

class ActionConfirmationTest {
    @Test fun `remembered device grant skips activity and can be revoked`() = runTest {
        var granted = false
        val editor = mockk<SharedPreferences.Editor>()
        val prefs = mockk<SharedPreferences>()
        val context = mockk<Context>()
        every { context.getSharedPreferences("device_access_consent", Context.MODE_PRIVATE) } returns prefs
        every { prefs.getBoolean("granted", false) } answers { granted }
        every { prefs.edit() } returns editor
        every { editor.putBoolean("granted", any()) } answers { granted = secondArg(); editor }
        every { editor.commit() } returns true
        assertFalse(ActionConfirmation.isDeviceAccessGranted(context))
        assertTrue(ActionConfirmation.grantDeviceAccess(context))
        for (action in listOf("screenshot", "tap", "swipe", "text", "keyevent")) {
            assertTrue(ActionConfirmation.ask(context, ToolRequest(requestId = action, action = action), {}))
        }
        verify(exactly = 0) { context.startActivity(any()) }
        ActionConfirmation.revokeDeviceAccess(context)
        assertFalse(ActionConfirmation.isDeviceAccessGranted(context))
        assertFalse(ActionConfirmation.canRemember("delete_event"))
        assertFalse(ActionConfirmation.canRemember("unknown"))
    }
}

package io.clawdroid

import android.app.Application
import android.util.Log
import io.clawdroid.backend.api.BackendLifecycle
import io.clawdroid.backend.api.BackendState
import io.clawdroid.backend.api.GatewaySettingsStore
import io.clawdroid.backend.config.ConfigApiClient
import io.clawdroid.backend.config.configModule
import io.clawdroid.core.data.remote.WebSocketClient
import io.clawdroid.di.appModule
import io.clawdroid.di.flavorModule
import io.clawdroid.receiver.NotificationHelper
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.filter
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.launch
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.koin.android.ext.koin.androidContext
import org.koin.core.context.startKoin
import java.net.URLEncoder

class ClawDroidApp : Application() {
    override fun onCreate() {
        super.onCreate()
        io.clawdroid.diagnostics.DiagnosticEvents.initialize(this)
        val koinApp = startKoin {
            androidContext(this@ClawDroidApp)
            modules(appModule, flavorModule, configModule)
        }
        NotificationHelper.createNotificationChannel(this)

        val koin = koinApp.koin
        val backendLifecycle: BackendLifecycle = koin.get()
        val settingsStore: GatewaySettingsStore = koin.get()
        val wsClient: WebSocketClient = koin.get()
        val configApiClient: ConfigApiClient = koin.get()
        val scope: CoroutineScope = koin.get()
        scope.launch {
            wsClient.connectionState.collect { state ->
                val code = when (state) {
                    io.clawdroid.core.domain.model.ConnectionState.CONNECTED -> "connected"
                    io.clawdroid.core.domain.model.ConnectionState.DISCONNECTED -> "disconnected"
                    else -> "connection_started"
                }
                io.clawdroid.diagnostics.DiagnosticEvents.record("websocket", code)
            }
        }
        scope.launch { backendLifecycle.start() }
        scope.launch {
            // Wait for backend to be running before connecting WebSocket
            combine(
                settingsStore.settings
                    .map { it.httpPort to it.apiKey }
                    .distinctUntilChanged(),
                backendLifecycle.state,
            ) { settings, state -> settings to state }
                .filter { (_, state) -> state == BackendState.RUNNING }
                .collect {
                    // Fetch WS connection info from config API
                    val wsUrl = fetchWsUrl(configApiClient)
                    wsClient.disconnect()
                    wsClient.wsUrl = wsUrl
                    // Also reconnect when credentials/backend readiness change at
                    // the same URL, or a previously disconnected client is retained.
                    wsClient.connect()
                }
        }
    }

    private suspend fun fetchWsUrl(configApiClient: ConfigApiClient): String {
        return try {
            val cfg = configApiClient.getConfig()
            val ws = cfg["channels"]?.jsonObject?.get("websocket")?.jsonObject
            if (ws != null) {
                val host = ws["host"]?.jsonPrimitive?.content ?: "127.0.0.1"
                val port = ws["port"]?.jsonPrimitive?.content ?: "18793"
                val path = ws["path"]?.jsonPrimitive?.content ?: "/ws"
                val wsApiKey = ws["api_key"]?.jsonPrimitive?.content ?: ""
                buildString {
                    append("ws://$host:$port$path")
                    if (wsApiKey.isNotEmpty()) {
                        append("?api_key=${URLEncoder.encode(wsApiKey, "UTF-8")}")
                    }
                }
            } else {
                DEFAULT_WS_URL
            }
        } catch (e: Exception) {
            Log.w(TAG, "Failed to fetch WS config from API, using defaults", e)
            DEFAULT_WS_URL
        }
    }

    companion object {
        private const val TAG = "ClawDroidApp"
        private const val DEFAULT_WS_URL = "ws://127.0.0.1:18793/ws"
    }
}

package io.clawdroid.core.data.remote

import android.util.Log
import io.ktor.client.HttpClient
import io.ktor.client.plugins.websocket.webSocket
import io.ktor.client.request.header
import io.ktor.websocket.Frame
import io.ktor.websocket.WebSocketSession
import io.ktor.websocket.readText
import io.clawdroid.core.data.remote.dto.WsIncoming
import io.clawdroid.core.data.remote.dto.WsOutgoing
import io.clawdroid.core.domain.model.ConnectionState
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import android.content.Context


class WebSocketClient(
    private val client: HttpClient,
    private val scope: CoroutineScope,
    private val clientId: String,
    private val clientType: String = "main",
    private val context: Context,
    private val apiKeyProvider: () -> String = { "" }
) {

    private val _connectionState = MutableStateFlow(ConnectionState.DISCONNECTED)
    val connectionState: StateFlow<ConnectionState> = _connectionState.asStateFlow()

    private val _setupRequired = MutableStateFlow(false)
    val setupRequired: StateFlow<Boolean> = _setupRequired.asStateFlow()

    private val _incomingMessages = MutableSharedFlow<WsOutgoing>(extraBufferCapacity = 64)
    val incomingMessages: SharedFlow<WsOutgoing> = _incomingMessages.asSharedFlow()

    private var session: WebSocketSession? = null
    private var connectJob: Job? = null
    private val json = Json { ignoreUnknownKeys = true }

    @Volatile var wsUrl: String = "ws://127.0.0.1:18793/ws"

    fun connect() {
        if (connectJob?.isActive == true) return
        connectJob = scope.launch {
            var retryDelay = INITIAL_DELAY
            while (isActive) {
                try {
                    _connectionState.value = ConnectionState.CONNECTING
                    _setupRequired.value = false
                    val currentWsUrl = wsUrl
                    val separator = if ('?' in currentWsUrl) '&' else '?'
                    val locale = "ru"
                    val url = "${currentWsUrl}${separator}client_id=$clientId&client_type=$clientType&locale=$locale"
                    client.webSocket(urlString = url, request = {
                        val key = apiKeyProvider()
                        if (key.isNotEmpty()) header("Authorization", "Bearer $key")
                    }) {
                        session = this
                        _connectionState.value = ConnectionState.CONNECTED
                        retryDelay = INITIAL_DELAY
                        for (frame in incoming) {
                            if (frame is Frame.Text) {
                                val text = frame.readText()
                                try {
                                    val msg = json.decodeFromString<WsOutgoing>(text)
                                    if (msg.type == "setup_required") {
                                        _setupRequired.value = true
                                    }
                                    _incomingMessages.emit(msg)
                                } catch (e: Exception) {
                                    Log.w(TAG, "Не удалось прочитать сообщение сервера")
                                }
                            }
                        }
                    }
                } catch (e: CancellationException) {
                    throw e
                } catch (e: Exception) {
                    Log.w(TAG, "Ошибка подключения к серверу")
                }
                session = null
                _connectionState.value = ConnectionState.RECONNECTING
                delay(retryDelay)
                retryDelay = (retryDelay * 2).coerceAtMost(MAX_DELAY)
            }
        }
    }

    fun disconnect() {
        connectJob?.cancel()
        connectJob = null
        session = null
        _connectionState.value = ConnectionState.DISCONNECTED
    }

    suspend fun send(dto: WsIncoming): Boolean {
        val activeSession = session ?: return false
        if (!activeSession.isActive) return false
        return try {
            activeSession.send(Frame.Text(json.encodeToString(dto)))
            true
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            Log.w(TAG, "Не удалось отправить сообщение")
            false
        }
    }

    companion object {
        private const val TAG = "WebSocketClient"
        private const val INITIAL_DELAY = 1000L
        private const val MAX_DELAY = 30000L
    }
}

package io.clawdroid.feature.chat

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import io.clawdroid.core.domain.usecase.ConnectChatUseCase
import io.clawdroid.core.domain.usecase.DisconnectChatUseCase
import io.clawdroid.core.domain.usecase.LoadMoreMessagesUseCase
import io.clawdroid.core.domain.usecase.ObserveConnectionUseCase
import io.clawdroid.core.domain.usecase.ObserveMessagesUseCase
import io.clawdroid.core.domain.usecase.ObserveStatusUseCase
import io.clawdroid.core.domain.usecase.SendMessageUseCase
import io.clawdroid.feature.chat.voice.VoiceModeManager
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

class ChatViewModel(
    private val sendMessage: SendMessageUseCase,
    private val observeMessages: ObserveMessagesUseCase,
    private val observeConnection: ObserveConnectionUseCase,
    private val observeStatus: ObserveStatusUseCase,
    private val loadMoreMessages: LoadMoreMessagesUseCase,
    private val connectChat: ConnectChatUseCase,
    private val disconnectChat: DisconnectChatUseCase,
    private val voiceModeManager: VoiceModeManager
) : ViewModel() {

    private val _uiState = MutableStateFlow(ChatUiState())
    val uiState: StateFlow<ChatUiState> = _uiState.asStateFlow()

    private val _scrollToBottom = MutableSharedFlow<Unit>(extraBufferCapacity = 1)
    val scrollToBottom = _scrollToBottom.asSharedFlow()

    init {
        connectChat()

        viewModelScope.launch {
            observeMessages().collect { messages ->
                _uiState.update { it.copy(messages = messages) }
            }
        }

        viewModelScope.launch {
            observeConnection().collect { state ->
                _uiState.update { it.copy(connectionState = state) }
            }
        }

        viewModelScope.launch {
            observeStatus().collect { label ->
                _uiState.update { it.copy(statusLabel = label) }
            }
        }

        viewModelScope.launch {
            voiceModeManager.state.collect { voiceState ->
                _uiState.update { it.copy(voiceModeState = voiceState) }
            }
        }
    }

    fun onEvent(event: ChatEvent) {
        when (event) {
            is ChatEvent.OnInputChanged -> {
                _uiState.update { it.copy(inputText = event.text) }
            }
            is ChatEvent.OnStopClick -> {
                voiceModeManager.stop()
                _uiState.update { it.copy(statusLabel = null) }
            }
            is ChatEvent.OnSendClick -> {
                val state = _uiState.value
                val text = state.inputText.trim()
                if (text.isEmpty() && state.pendingImages.isEmpty()) return
                _scrollToBottom.tryEmit(Unit)
                _uiState.update { it.copy(inputText = "", pendingImages = emptyList()) }
                viewModelScope.launch {
                    try {
                        sendMessage(text, state.pendingImages)
                    } catch (e: Exception) {
                        _uiState.update { it.copy(error = e.message) }
                    }
                }
            }
            is ChatEvent.OnImageAdded -> {
                _uiState.update { it.copy(pendingImages = it.pendingImages + event.image) }
            }
            is ChatEvent.OnImageRemoved -> {
                _uiState.update {
                    it.copy(pendingImages = it.pendingImages.filterIndexed { i, _ -> i != event.index })
                }
            }
            is ChatEvent.OnLoadMore -> {
                loadMoreMessages()
            }
            is ChatEvent.OnError -> {
                _uiState.update { it.copy(error = event.message) }
            }
            is ChatEvent.OnErrorDismissed -> {
                _uiState.update { it.copy(error = null) }
            }
            is ChatEvent.OnVoiceModeStart -> {
                voiceModeManager.start(viewModelScope)
            }
            is ChatEvent.OnVoiceModeStop -> {
                voiceModeManager.stop()
            }
            is ChatEvent.OnVoiceModeInterrupt -> {
                voiceModeManager.interrupt()
            }
            is ChatEvent.OnVoiceCameraToggle -> {
                voiceModeManager.toggleCamera()
            }
        }
    }

    override fun onCleared() {
        super.onCleared()
        voiceModeManager.destroy()
        // The application owns this shared connection. Navigating away must not
        // disconnect the socket used by retained chat state and background tools.
    }
}

package io.clawdroid.core.data.repository

import android.content.Context
import android.util.Log
import io.ktor.client.HttpClient
import io.clawdroid.core.data.remote.WebSocketClient
import io.clawdroid.core.data.remote.dto.ToolRequest
import io.clawdroid.core.data.remote.dto.WsIncoming
import io.clawdroid.core.domain.model.AssistantMessage
import io.clawdroid.core.domain.model.ConnectionState
import io.clawdroid.core.domain.repository.AssistantConnection
import kotlinx.coroutines.Job
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineStart
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.json.Json
import java.util.UUID

typealias ToolRequestCallback = suspend (ToolRequest) -> String

class AssistantConnectionImpl(
    private val httpClient: HttpClient,
    private val context: Context,
    apiKeyProvider: () -> String = { "" }
) : AssistantConnection {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private val clientId = UUID.randomUUID().toString()
    private val wsClient = WebSocketClient(httpClient, scope, clientId, "assistant", context = context, apiKeyProvider = apiKeyProvider)
    private val generation = AtomicLong(0)
    private val toolJobs = ConcurrentHashMap<String, Job>()

    private val json = Json { ignoreUnknownKeys = true }

    private val _messages = MutableSharedFlow<AssistantMessage>(extraBufferCapacity = 64)
    override val messages: SharedFlow<AssistantMessage> = _messages.asSharedFlow()

    private val _statusText = MutableStateFlow<String?>(null)
    override val statusText: StateFlow<String?> = _statusText.asStateFlow()

    override val connectionState: StateFlow<ConnectionState> = wsClient.connectionState

    var onToolRequest: ToolRequestCallback? = null
    var onExit: ((String?) -> Unit)? = null

    init {
        scope.launch {
            wsClient.incomingMessages.collect { dto ->
                if (generation.get() > 0L && dto.generation != generation.get() && dto.type != "setup_required") return@collect
                when (dto.type) {
                    "status" -> _statusText.value = dto.content
                    "cancelled" -> _statusText.value = null
                    "status_end" -> _statusText.value = null
                    "tool_cancel" -> {
                        val request = json.decodeFromString<ToolRequest>(dto.content)
                        toolJobs.remove(request.requestId)?.cancel()
                    }
                    "tool_request" -> handleToolRequest(dto.content)
                    "exit" -> onExit?.invoke(dto.content)
                    else -> {
                        _messages.emit(AssistantMessage(content = dto.content, type = dto.type))
                    }
                }
            }
        }
    }

    private fun handleToolRequest(content: String) {
        val request = try { json.decodeFromString<ToolRequest>(content) } catch (e: Exception) { return }
        if (request.generation != generation.get()) return
        val job = scope.launch(start = CoroutineStart.LAZY) {
            try {
                if (request.generation != generation.get()) return@launch
                val callback = onToolRequest
                val resultContent = if (callback != null) {
                    callback(request)
                } else {
                    "error: tool request handler not configured"
                }

                val response = WsIncoming(
                    content = resultContent,
                    type = "tool_response",
                    requestId = request.requestId,
                    generation = request.generation
                )
                if (request.generation == generation.get()) wsClient.send(response)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                Log.e(TAG, "Failed to handle tool request", e)
            } finally {
                toolJobs.remove(request.requestId)
            }
        }
        toolJobs[request.requestId] = job
        if (request.generation != generation.get()) job.cancel() else job.start()
    }

    override fun connect(wsUrl: String) {
        wsClient.wsUrl = wsUrl
        wsClient.connect()
    }

    override fun stop() {
        val next = generation.incrementAndGet()
        toolJobs.values.forEach { it.cancel() }
        toolJobs.clear()
        _statusText.value = null
        scope.launch { wsClient.send(WsIncoming(content = "", type = "cancel", generation = next)) }
    }

    override fun disconnect() {
        stop()
        wsClient.disconnect()
        scope.cancel()
    }

    override suspend fun send(text: String, images: List<String>, inputMode: String) {
        toolJobs.values.forEach { it.cancel() }
        val next = generation.incrementAndGet()
        val dto = WsIncoming(
            generation = next,
            content = text,
            images = images.ifEmpty { null },
            inputMode = inputMode
        )
        check(wsClient.send(dto)) { "Нет подключения к локальному серверу Джарвиса. Дождитесь подключения и повторите запрос." }
    }

    companion object {
        private const val TAG = "AssistantConnectionImpl"
    }
}

package io.clawdroid.core.data.repository

import android.util.Log
import io.clawdroid.core.data.local.ImageFileStorage
import io.clawdroid.core.data.local.dao.MessageDao
import io.clawdroid.core.data.mapper.MessageMapper
import io.clawdroid.core.data.remote.WebSocketClient
import io.clawdroid.core.data.remote.dto.ToolRequest
import io.clawdroid.core.data.remote.dto.WsIncoming
import io.clawdroid.core.domain.model.ChatMessage
import io.clawdroid.core.domain.model.ConnectionState
import io.clawdroid.core.domain.model.ImageAttachment
import io.clawdroid.core.domain.model.MessageStatus
import io.clawdroid.core.domain.repository.ChatRepository
import kotlinx.coroutines.Job
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineStart
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.flatMapLatest
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.serialization.json.Json

class ChatRepositoryImpl(
    private val webSocketClient: WebSocketClient,
    private val messageDao: MessageDao,
    private val scope: CoroutineScope,
    private val imageFileStorage: ImageFileStorage
) : ChatRepository {

    private val generation = AtomicLong(0)
    private val toolJobs = ConcurrentHashMap<String, Job>()

    private val json = Json { ignoreUnknownKeys = true }
    var onToolRequest: (suspend (ToolRequest) -> String)? = null

    private val _displayLimit = MutableStateFlow(INITIAL_LOAD_COUNT)
    private val _statusLabel = MutableStateFlow<String?>(null)

    @Suppress("OPT_IN_USAGE")
    override val messages: StateFlow<List<ChatMessage>> =
        _displayLimit.flatMapLatest { limit ->
            messageDao.getRecentMessages(limit)
        }.map { entities ->
            entities.map { MessageMapper.toDomain(it) }
        }.stateIn(scope, SharingStarted.Lazily, emptyList())

    override val connectionState: StateFlow<ConnectionState> = webSocketClient.connectionState

    override val statusLabel: StateFlow<String?> = _statusLabel.asStateFlow()

    init {
        scope.launch {
            webSocketClient.incomingMessages.collect { dto ->
                if (generation.get() > 0L && dto.generation != generation.get() && dto.type != "setup_required") return@collect
                when (dto.type) {
                    "status" -> _statusLabel.value = dto.content
                    "cancelled" -> _statusLabel.value = null
                    "status_end" -> _statusLabel.value = null
                    "tool_cancel" -> {
                        val request = json.decodeFromString<ToolRequest>(dto.content)
                        toolJobs.remove(request.requestId)?.cancel()
                    }
                    "tool_request" -> handleToolRequest(dto.content)
                    "exit", "setup_required" -> { /* ignored in chat mode */ }
                    else -> {
                        _statusLabel.value = null
                        val entity = MessageMapper.toEntity(dto)
                        messageDao.insert(entity)
                    }
                }
            }
        }
    }

    override suspend fun sendMessage(text: String, images: List<ImageAttachment>, inputMode: String?) {
        val results = images.map { imageFileStorage.saveFromUri(it.uri) }
        val entity = MessageMapper.toEntity(text, results.map { it.imageData }, MessageStatus.SENDING)
        messageDao.insert(entity)
        toolJobs.values.forEach { it.cancel() }
        val next = generation.incrementAndGet()
        val wsDto = MessageMapper.toWsIncoming(text, results.map { it.base64 }, inputMode).copy(generation = next)
        val success = webSocketClient.send(wsDto)
        messageDao.update(entity.copy(status = if (success) MessageStatus.SENT.name else MessageStatus.FAILED.name))
        check(success) { "Нет подключения к локальному серверу Джарвиса. Дождитесь подключения и повторите запрос." }
    }

    override fun loadMore() {
        _displayLimit.update { it + PAGE_SIZE }
    }

    override fun connect() {
        webSocketClient.connect()
    }

    override fun stop() {
        val next = generation.incrementAndGet()
        toolJobs.values.forEach { it.cancel() }
        toolJobs.clear()
        _statusLabel.value = null
        scope.launch { webSocketClient.send(WsIncoming(content = "", type = "cancel", generation = next)) }
    }

    override fun disconnect() {
        stop()
        webSocketClient.disconnect()
    }

    private fun handleToolRequest(content: String) {
        val request = try { json.decodeFromString<ToolRequest>(content) } catch (e: Exception) { return }
        if (request.generation != generation.get()) return
        val job = scope.launch(start = CoroutineStart.LAZY) {
            try {
                if (request.generation != generation.get()) return@launch
                val callback = onToolRequest
                val resultContent = if (callback != null) {
                    callback(request)
                } else {
                    "tool request handler not configured"
                }
                val response = WsIncoming(
                    content = resultContent,
                    type = "tool_response",
                    requestId = request.requestId,
                    generation = request.generation
                )
                if (request.generation == generation.get()) webSocketClient.send(response)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                Log.e(TAG, "Failed to handle tool request", e)
            } finally {
                toolJobs.remove(request.requestId)
            }
        }
        toolJobs[request.requestId] = job
        if (request.generation != generation.get()) job.cancel() else job.start()
    }

    companion object {
        private const val TAG = "ChatRepositoryImpl"
        const val INITIAL_LOAD_COUNT = 50
        const val PAGE_SIZE = 30
    }
}

package io.clawdroid.feature.chat

